mapper.sql:
SELECT activity.activity_id, COUNT(DISTINCT rel.order_id) AS all_order_num FROM community_activity AS activity LEFT JOIN community_order_rel_activity AS rel ON activity.activity_id = rel.activity_id WHERE activity.chief_id = #{chiefId}
AND activity.activity_status = #{activityStatus}
GROUP BY activity.activity_id

mapper.select:
SELECT agg.activity_id
FROM (

) AS agg
ORDER BY agg.all_order_num DESC, agg.activity_id DESC
LIMIT #{offset}, #{limit}

